import numpy as np
import torch
import math
from torchvision.transforms.v2 import functional as F

from transformers.image_processing_utils import BatchFeature
from transformers.image_utils import (
    OPENAI_CLIP_MEAN,
    OPENAI_CLIP_STD,
    ChannelDimension,
    PILImageResampling,
    SizeDict,
    get_image_size,
)
from transformers.processing_utils import Unpack, VideosKwargs
from transformers.utils import TensorType, add_start_docstrings
from transformers.video_processing_utils import BASE_VIDEO_PROCESSOR_DOCSTRING, BaseVideoProcessor
from transformers.video_utils import VideoMetadata, group_videos_by_shape, reorder_videos
from .image_processing_glm5next import ResizeMode, _get_pad_content_size, smart_resize

class Glm5nextVideoProcessorInitKwargs(VideosKwargs, total=False):
    max_image_size: dict[str, int]
    patch_size: int
    temporal_patch_size: int
    merge_size: int
    max_duration: int
    patch_expand_factor: int
    min_image_tokens: int
    max_image_tokens: int
    fps_interval: int
    max_frame_count_dynamic: int
    resize_mode: ResizeMode


@add_start_docstrings(
    "Constructs a fast GLM-5-Next image processor that dynamically resizes videos based on the original videos.",
    BASE_VIDEO_PROCESSOR_DOCSTRING,
    """
        patch_size (`int`, *optional*, defaults to 14):
            The spacial patch size of the vision encoder.
        temporal_patch_size (`int`, *optional*, defaults to 2):
            The temporal patch size of the vision encoder.
        merge_size (`int`, *optional*, defaults to 2):
            The merge size of the vision encoder to llm encoder.
    """,
)
class Glm5nextVideoProcessor(BaseVideoProcessor):
    resample = PILImageResampling.BICUBIC
    # `size` is unused (kept only because the base class expects the attribute); resize is driven
    # by min_image_tokens/max_image_tokens.
    size = None
    max_image_size = {"longest_edge": 28 * 28 * 2 * 30000}
    image_mean = None
    image_std = None
    do_resize = True
    do_rescale = True
    do_normalize = True
    do_convert_rgb = True
    do_sample_frames = True
    patch_size = None
    temporal_patch_size = None
    patch_expand_factor = None
    max_duration = 300
    merge_size = None
    min_image_tokens = None
    max_image_tokens = None
    valid_kwargs = Glm5nextVideoProcessorInitKwargs
    num_frames = 16
    fps = 2
    fps_interval = None
    max_frame_count_dynamic = None
    resize_mode = "pad"

    model_input_names = ["pixel_values_videos", "video_grid_thw"]

    def __init__(self, **kwargs: Unpack[Glm5nextVideoProcessorInitKwargs]):
        super().__init__(**kwargs)
        # min/max pixels bound the full t*h*w volume where needed:
        # tokens * temporal_patch_size * (patch_size*merge_size)**2.
        assert (
            self.min_image_tokens is not None and self.max_image_tokens is not None
        ), "min_image_tokens and max_image_tokens must be provided."
        if self.resize_mode not in ("resize", "pad"):
            raise ValueError("resize_mode must be either 'resize' or 'pad'.")

    def _validate_preprocess_kwargs(self, size: Optional[SizeDict] = None, **kwargs):
        # Resize bounds are derived from min_image_tokens/max_image_tokens, so `size` is unused.
        # Pass a non-null placeholder so the base check (which requires `size` when do_resize) passes.
        return super()._validate_preprocess_kwargs(size=size or SizeDict(longest_edge=1), **kwargs)

    def _resize_or_pad(
        self,
        stacked_images: "torch.Tensor",
        target_height: int,
        target_width: int,
        resize_mode: ResizeMode,
        interpolation,
        allow_upscale: bool = False,
    ) -> "torch.Tensor":
        height, width = stacked_images.shape[-2:]

        if resize_mode == "resize":
            return self.resize(
                stacked_images,
                size=SizeDict(height=target_height, width=target_width),
                interpolation=interpolation,
            )

        if resize_mode != "pad":
            raise ValueError("resize_mode must be either 'resize' or 'pad'.")

        content_height, content_width = _get_pad_content_size(
            image_height=height,
            image_width=width,
            canvas_height=target_height,
            canvas_width=target_width,
            allow_upscale=allow_upscale,
        )

        if (content_height, content_width) != (height, width):
            stacked_images = self.resize(
                stacked_images,
                size=SizeDict(height=content_height, width=content_width),
                interpolation=interpolation,
            )

        # torchvision padding order: [left, top, right, bottom] -> pad only right and bottom.
        return F.pad(
            stacked_images,
            padding=[0, 0, target_width - content_width, target_height - content_height],
            fill=0,
        )

    def sample_frames(
        self,
        metadata: VideoMetadata,
        fps: Optional[Union[int, float]] = None,
        **kwargs,
    ):
        """
        Args:
            metadata (`VideoMetadata`):
                Metadata of the video containing information about total duration, fps and total number of frames.
            fps (`int` or `float`, *optional*):
                Target frames to sample per second. Defaults to `self.fps`.
        Returns:
            np.ndarray:
                Indices to sample video frames.
        """
        if metadata is None or getattr(metadata, "fps", None) is None:
            raise ValueError(
                "Asked to sample frames per second but no video metadata was provided which is required when sampling in Glm5next. "
                "Please pass in `VideoMetadata` object or set `do_sample_frames=False`"
            )

        total_frames = metadata.total_num_frames
        max_frame_idx = total_frames - 1
        duration = metadata.duration or round(max_frame_idx / metadata.fps) + 1

        MAX_FRAME_COUNT_DYNAMIC = kwargs.get("max_frames") or self.max_frame_count_dynamic
        effective_duration = duration
        target_fps = kwargs.get("target_fps") or self.fps_interval

        extract_t = int(effective_duration * target_fps)
        extract_t = min(extract_t, MAX_FRAME_COUNT_DYNAMIC)

        duration_per_frame = 1 / metadata.fps
        timestamps = [i * duration_per_frame for i in range(total_frames)]
        max_second = int(duration)

        if total_frames < extract_t:
            # frame_indices = np.linspace(0, total_frames - 1, extract_t, dtype=int).tolist()
            # Bug: The original np.linspace causes each frame to be sampled an uneven number of times (e.g., for a 3-second video at 1 fps, sampling at 2 fps yields frame indices [0,0,1,1,2,3] instead of [0,0,1,1,2,2]). This degrades model performance on time-sensitive tasks, e.g., a 4-point drop on the video object tracking task (vidstg).
            # Fix: Directly sample at evenly spaced timestamps, ensuring that each frame is sampled equally often.
            frame_indices = [math.floor(_i * total_frames / extract_t) for _i in range(extract_t)]
        else:
            frame_indices = []
            current_second = 0
            inv_fps = 1 / (self.temporal_patch_size * target_fps)
            for frame_index in range(total_frames):
                if timestamps[frame_index] >= current_second:
                    current_second += inv_fps
                    frame_indices.append(frame_index)
                    if current_second >= max_second:
                        break

        if len(frame_indices) < extract_t:
            if len(frame_indices) == 0:
                start, end = 0, max(total_frames - 1, 0)
            else:
                start, end = frame_indices[0], frame_indices[-1]
            frame_indices = np.linspace(start, end, extract_t, dtype=int).tolist()
        elif len(frame_indices) > extract_t:
            frame_indices = np.linspace(0, total_frames - 1, extract_t, dtype=int).tolist()

        seen, uniq = set(), []
        for idx in frame_indices:
            if idx not in seen:
                seen.add(idx)
                uniq.append(idx)

        if len(uniq) & 1:
            uniq.append(uniq[-1])

        return np.array(uniq)

    def _preprocess(
        self,
        videos: list[torch.Tensor],
        do_convert_rgb: bool = True,
        do_resize: bool = True,
        interpolation: PILImageResampling = PILImageResampling.BICUBIC,
        do_rescale: bool = True,
        rescale_factor: float = 1 / 255.0,
        do_normalize: bool = True,
        image_mean: Optional[Union[float, list[float]]] = None,
        image_std: Optional[Union[float, list[float]]] = None,
        patch_size: Optional[int] = None,
        temporal_patch_size: Optional[int] = None,
        patch_expand_factor: Optional[int] = None,
        merge_size: Optional[int] = None,
        resize_mode: ResizeMode = "pad",
        min_image_tokens: Optional[int] = None,
        max_image_tokens: Optional[int] = None,
        return_tensors: Optional[Union[str, TensorType]] = None,
        **kwargs,
    ):
        min_image_tokens = (
            min_image_tokens if min_image_tokens is not None else self.min_image_tokens
        )
        max_image_tokens = (
            max_image_tokens if max_image_tokens is not None else self.max_image_tokens
        )
        grouped_videos, grouped_videos_index = group_videos_by_shape(videos)
        resized_videos_grouped = {}
        for shape, stacked_videos in grouped_videos.items():
            B, T, C, H, W = stacked_videos.shape
            num_frames, height, width = T, H, W
            if do_resize:
                factor = temporal_patch_size * (patch_size * merge_size) ** 2
                min_pixels = self.min_image_tokens * factor
                max_pixels = self.max_image_tokens * factor
                resized_height, resized_width = smart_resize(
                    t=num_frames,
                    h=height,
                    w=width,
                    t_factor=temporal_patch_size,
                    h_factor=patch_size * merge_size * patch_expand_factor,
                    w_factor=patch_size * merge_size * patch_expand_factor,
                    min_pixels=min_image_tokens * factor,
                    max_pixels=max_image_tokens * factor,
                )
                stacked_videos = stacked_videos.view(B * T, C, H, W)
                stacked_videos = self._resize_or_pad(
                    stacked_images=stacked_videos,
                    target_height=resized_height,
                    target_width=resized_width,
                    resize_mode=resize_mode,
                    interpolation=interpolation,
                    allow_upscale=(num_frames * height * width < min_pixels),
                )
                stacked_videos = stacked_videos.view(B, T, C, resized_height, resized_width)
            resized_videos_grouped[shape] = stacked_videos
        resized_videos = reorder_videos(resized_videos_grouped, grouped_videos_index)

        # Group videos by size for further processing
        # Needed in case do_resize is False, or resize returns videos with different sizes
        grouped_videos, grouped_videos_index = group_videos_by_shape(resized_videos)
        processed_videos_grouped = {}
        processed_grids = {}
        for shape, stacked_videos in grouped_videos.items():
            resized_height, resized_width = get_image_size(stacked_videos[0], channel_dim=ChannelDimension.FIRST)

            # Fused rescale and normalize
            stacked_videos = self.rescale_and_normalize(
                stacked_videos, do_rescale, rescale_factor, do_normalize, image_mean, image_std
            )
            patches = stacked_videos

            # Check that videos have `num_frames` divisible by `temporal_patch_size`
            if patches.shape[1] % temporal_patch_size != 0:
                repeats = patches[:, -1:].repeat(1, temporal_patch_size - 1, 1, 1, 1)
                patches = torch.cat([patches, repeats], dim=1)
            batch_size, grid_t, channel = patches.shape[:3]
            grid_t = grid_t // temporal_patch_size
            grid_h, grid_w = resized_height // patch_size, resized_width // patch_size

            patches = patches.view(
                batch_size,
                grid_t,
                temporal_patch_size,
                channel,
                grid_h // merge_size,
                merge_size,
                patch_size,
                grid_w // merge_size,
                merge_size,
                patch_size,
            )
            patches = patches.permute(0, 1, 4, 7, 5, 8, 3, 2, 6, 9)
            flatten_patches = patches.reshape(
                batch_size,
                grid_t * grid_h * grid_w,
                channel * temporal_patch_size * patch_size * patch_size,
            )

            processed_videos_grouped[shape] = flatten_patches
            processed_grids[shape] = [[grid_t, grid_h, grid_w]] * batch_size

        processed_videos = reorder_videos(processed_videos_grouped, grouped_videos_index)
        processed_grids = reorder_videos(processed_grids, grouped_videos_index)
        pixel_values_videos = torch.cat(processed_videos, dim=0)
        video_grid_thw = torch.tensor(processed_grids)
        data = {
            "pixel_values_videos": pixel_values_videos,
            "video_grid_thw": video_grid_thw,
        }

        return BatchFeature(data=data, tensor_type=return_tensors)


__all__ = ["Glm5nextVideoProcessor"]